export function middleware(request: NextRequest) {
  const path = request.nextUrl.pathname;

  // Match root-level paths (with or without trailing slash)
  const match = path.match(/^\/([^\/]+)\/?$/);
  if (match) {
    const slug = match[1];
    if (BLOG_SLUGS.has(slug)) {
      const url = new URL(`/blog/${slug}`, request.url);
      return NextResponse.redirect(url, 301);
    }
  }

  return NextResponse.next();
}

export const config = {
  // Only run on root-level paths, skip known static/api/asset routes
  matcher: [
    "/((?!api|_next|images|videos|fonts|favicon|robots|sitemap|manifest).*)",
  ],
};
